RESOURCES = {"Minerals": 1200, "Gas": 600}
print("Strategy economy example")
for k, v in RESOURCES.items():
    print("%s: %d" % (k, v))
print("Army cost example: 800 minerals, 400 gas")
print("Remaining after army: %d minerals, %d gas" % (1200 - 800, 600 - 400))

MAPS = {"Map A": 0.65, "Map B": 0.45, "Map C": 0.70}
print("Map win rates example")
for k, v in MAPS.items():
    print("%s: %.0f%%" % (k, v * 100.0))
print("Best map: %s" % max(MAPS, key=MAPS.get))
print("Weakest map: %s (target for practice)" % min(MAPS, key=MAPS.get))
